def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find solid separator rows. The patterned area on either side is a
    # stencil: extend the upper pattern into matching background cells below.
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    if sep_rows:
        # Use the largest run of solid rows as the divider.
        runs = []
        for r in sep_rows:
            if not runs or r > runs[-1][-1] + 1:
                runs.append([r])
            else:
                runs[-1].append(r)
        divider = max(runs, key=len)
        top_end = divider[0]
        bot_start = divider[-1] + 1
        upper = [r for r in range(top_end) if len(set(grid[r])) > 1]
        lower = [r for r in range(bot_start, h) if len(set(grid[r])) > 1]

        if upper and lower:
            # Color repeated in the divider is background; the other color
            # in the two motifs is the stencil foreground.
            bg = grid[divider[0]][0]
            fg_counts = {}
            for r in upper:
                for x in grid[r]:
                    if x != bg:
                        fg_counts[x] = fg_counts.get(x, 0) + 1
            if fg_counts:
                fg = max(fg_counts, key=fg_counts.get)
                n = min(len(upper), len(lower))
                for i in range(n):
                    ur = upper[len(upper) - n + i]
                    lr = lower[i]
                    for c in range(w):
                        if grid[ur][c] == fg and grid[lr][c] == bg:
                            out[lr][c] = 1
    return out
